insert into public.calendar_posts
  (day, topic_key, format, title, caption, hashtags, status, sort_order, updated_at)
values
  ('2026-12-01', 'fundraising-mobilizing', 'Reel', 'Giving Tuesday — matched donation', 'Greetings EG Family! Today every gift goes further: with matched funding, each new donor unlocks more support for youth-led restoration. Give what you can, then share this with 3 people. Link in bio! #GivingTuesday #EarthGuardians #ClimateAction', '#GivingTuesday #EarthGuardians #ClimateAction', 'planned', 0, now()),
  ('2026-12-02', 'climate-action', 'Carousel', 'COP31: what came out of the negotiations', 'Greetings EG Family! COP31 closed — here are 3 wins, 2 stalls, and what youth networks are watching next. Swipe, then tell us: which one matters most to your community? #COP31 #ChooseActionNow #ClimateJustice', '#COP31 #ChooseActionNow #ClimateJustice', 'planned', 0, now()),
  ('2026-12-03', 'crews-community', 'Carousel', 'Crew of the month: how to start from zero', 'Greetings EG Family! Crew spotlight: from first meeting to first action in 30 days. Swipe for the exact 4 steps they used — steal them for your city. Start a crew: link in bio. #EarthGuardiansCrews #YouthPower', '#EarthGuardiansCrews #YouthPower', 'planned', 0, now()),
  ('2026-12-04', 'trainings-webinars', 'Photo', 'Masterclass #6 — registration is open', 'Greetings EG Family! New masterclass, new tools: register free and bring a friend. Save your spot — link in bio. #Masterclass #EarthGuardians #Leadership', '#Masterclass #EarthGuardians #Leadership', 'planned', 0, now()),
  ('2026-12-05', 'awareness-days', 'Reel', 'World Soil Day', 'Happy World Soil Day 🌱 Healthy soil stores carbon, holds water and feeds communities. One action for today: skip the chemicals, feed your soil with compost. #WorldSoilDay #RegenerativeAgriculture #EarthGuardians', '#WorldSoilDay #RegenerativeAgriculture #EarthGuardians', 'planned', 0, now()),
  ('2026-12-06', 'leaders-bts', 'Reel', 'Behind the scenes: the field team', 'Greetings EG Family! Sunday behind-the-scenes: what a field week actually looks like — mud, meetings, planting and a lot of hope. #BehindTheScenes #EarthGuardians', '#BehindTheScenes #EarthGuardians', 'planned', 0, now()),
  ('2026-12-07', 'impact-restoration', 'Carousel', 'Togo in numbers: 21,000 trees', 'Quick math that might surprise you: 21,000 trees, 52 hectares restored, 200 growers trained — all in 3 years in one village in Togo. Swipe for the full impact sheet. #ImpactNumbers #Togo #Restoration', '#ImpactNumbers #Togo #Restoration', 'planned', 0, now()),
  ('2026-12-08', 'indigenous-justice', 'Reel', 'Indigenous Voices: IYI alumni', 'Greetings EG Family! An IYI alum shares what changed after training — and the campaign they built back home. Applications for 2027 open soon. #IndigenousYouth #IYI #ClimateJustice', '#IndigenousYouth #IYI #ClimateJustice', 'planned', 0, now()),
  ('2026-12-09', 'water-oceans', 'Reel', 'Blue Planet Voices — new episode', 'New episode of Blue Planet Voices: how communities are defending water where they live. Full episode — link in bio. #BluePlanetVoices #WaterIsLife', '#BluePlanetVoices #WaterIsLife', 'planned', 0, now()),
  ('2026-12-10', 'awareness-days', 'Carousel', 'Human Rights Day', 'Human rights are climate rights. Swipe: 5 stories of communities defending land, water and future — and how to stand with them. #HumanRightsDay #ClimateJustice #EarthGuardians', '#HumanRightsDay #ClimateJustice #EarthGuardians', 'planned', 0, now()),
  ('2026-12-11', 'trainings-webinars', 'Carousel', '5 ways to prepare for a training', '5 ways to get ready for a leadership training (works for any program): set an intention, map your local issue, bring a question, find an accountability buddy, plan your first action. #LeadershipTraining #EarthGuardians', '#LeadershipTraining #EarthGuardians', 'planned', 0, now()),
  ('2026-12-12', 'crews-community', 'Reel', 'Saturday micro-action', 'CHOOSE ACTION NOW — weekend edition: pick ONE micro-action (cleanup, native plant, letter to an official), do it today, post it and tag 2 friends. 🏢 #ChooseActionNow #YouthClimateAction', '#ChooseActionNow #YouthClimateAction', 'planned', 0, now()),
  ('2026-12-13', 'leaders-bts', 'Photo', 'Sunday reflection: why we keep going', '“We don’t need more spectators — we need people who bring the fight for change into their everyday lives.” Which part of your everyday can become action? #YouthPower #EarthGuardians', '#YouthPower #EarthGuardians', 'planned', 0, now()),
  ('2026-12-14', 'partners-collabs', 'Carousel', 'Green Jobs Pavilion: careers in food & climate', 'Greetings EG Family! Green Jobs Pavilion is back — panels on food, agriculture and climate careers in LA and SF. Swipe for sessions and free registration. @greenjobsboard #GreenJobs #ClimateCareers', '#GreenJobs #ClimateCareers', 'planned', 0, now()),
  ('2026-12-15', 'climate-action', 'Carousel', 'Mid-month challenge', 'Halfway through the challenge! How many actions have you taken? Comment your count 👍 and screenshot your action for our next roundup. #ChooseActionNow #COP31', '#ChooseActionNow #COP31', 'planned', 0, now()),
  ('2026-12-16', 'impact-restoration', 'Photo', 'Before & after: Tagba, Togo', 'Before / after from Tagba community forest, Togo — sustainable community forest management with @worldrainforestfund. Same land, different future. #Restoration #Togo #EarthGuardians', '#Restoration #Togo #EarthGuardians', 'planned', 0, now()),
  ('2026-12-17', 'trainings-webinars', 'Carousel', 'FAQ: trainings and 2027 applications', 'FAQ Friday-early edition: who can apply, what’s covered, deadlines and how selection works. Swipe — and send this to someone who should apply. Link in bio. #ApplyNow #EarthGuardians', '#ApplyNow #EarthGuardians', 'planned', 0, now()),
  ('2026-12-18', 'awareness-days', 'Carousel', 'International Migrants Day', 'Climate change is already moving people. Swipe: 3 things to know about climate migration and how youth networks are supporting displaced communities. #MigrationDay #ClimateJustice', '#MigrationDay #ClimateJustice', 'planned', 0, now()),
  ('2026-12-19', 'fundraising-mobilizing', 'Reel', 'Final week: year-end goal', 'One week left in our year-end goal. Every share counts as much as every gift — repost this and tag 5 people who care about youth-led climate action. Link in bio. #Donate #YearEnd #EarthGuardians', '#Donate #YearEnd #EarthGuardians', 'planned', 0, now()),
  ('2026-12-20', 'water-oceans', 'Reel', 'Blue Planet Voices — featured episode', 'Sunday replay: our most-watched episode on water defense and community-led solutions. Full episode in bio. #WaterIsLove #BluePlanetVoices', '#WaterIsLove #BluePlanetVoices', 'planned', 0, now()),
  ('2026-12-21', 'awareness-days', 'Photo', 'Solstice: cycles and new beginnings', 'Happy solstice ❄️ Shortest day, longest night — nature’s reminder that every cycle turns. What are you ready to compost this year so 2027 can grow? #Solstice #EarthGuardians', '#Solstice #EarthGuardians', 'planned', 0, now()),
  ('2026-12-22', 'crews-community', 'Carousel', 'Crew spotlight: quick questions', 'Crew spotlight, rapid-fire: 6 questions, one crew, zero filter — what surprised them, what failed, what they’d repeat. Swipe. #EarthGuardiansCrews #YouthClimateAction', '#EarthGuardiansCrews #YouthClimateAction', 'planned', 0, now()),
  ('2026-12-23', 'leaders-bts', 'Reel', 'The ED''s end-of-year message', 'A year-end message from our Executive Director: thank you, what’s ahead, and one ask for every person watching. 💖 #EarthGuardians #YouthPower', '#EarthGuardians #YouthPower', 'planned', 0, now()),
  ('2026-12-24', 'indigenous-justice', 'Photo', 'Culture, celebration and territory', 'From our Indigenous youth network to yours: celebrations rooted in land, ancestors and community. Happy holidays from Earth Guardians. 🎄 #IndigenousKnowledge #EarthGuardians', '#IndigenousKnowledge #EarthGuardians', 'planned', 0, now()),
  ('2026-12-25', 'impact-restoration', 'Photo', 'Gratitude: 3 wins of 2026', 'Greetings EG Family! Today, gratitude only: 3 things our network made possible in 2026 — and it was all you. Thank you. 💖 #Gratitude #EarthGuardians', '#Gratitude #EarthGuardians', 'planned', 0, now()),
  ('2026-12-26', 'crews-community', 'Reel', 'Action kit for 2027', 'Boxing Day, but make it action: your free starter kit for a crew in 2027 — meeting agenda, first-action checklist and outreach templates. Link in bio. #StartACrew #EarthGuardians', '#StartACrew #EarthGuardians', 'planned', 0, now()),
  ('2026-12-27', 'leaders-bts', 'Carousel', 'Reflection: what you learned in 2026', 'Sunday reflection: swipe through 5 journal prompts our youth leaders use at year end — then answer one in the comments. #Reflection #YouthLeadership', '#Reflection #YouthLeadership', 'planned', 0, now()),
  ('2026-12-28', 'impact-restoration', 'Carousel', '2026 impact report in numbers', '2026 in numbers: crews started, young leaders trained, actions taken and hectares supported. Swipe for the full report — none of it happened without you. #ImpactReport #EarthGuardians', '#ImpactReport #EarthGuardians', 'planned', 0, now()),
  ('2026-12-29', 'climate-action', 'Carousel', 'Heading to COP32: our focus for 2027', 'From COP31 to COP32: 3 priorities our network will push in 2027 — and where you plug in. Swipe, then pick your lane. #COP32 #ChooseActionNow #ClimateJustice', '#COP32 #ChooseActionNow #ClimateJustice', 'planned', 0, now()),
  ('2026-12-30', 'partners-collabs', 'Carousel', 'Partners who made 2026 happen', 'Year-end shoutout to the partners who showed up for youth-led climate action all year — swipe to see them all, then go follow and thank them. 👏 #Partnerships #EarthGuardians', '#Partnerships #EarthGuardians', 'planned', 0, now()),
  ('2026-12-31', 'fundraising-mobilizing', 'Reel', '2026 before & after + collective resolution', 'Last day of 2026 🎆 Before/after of our year, and one collective resolution for 2027: act where you are. Drop yours below — we’re reading every one. #NewYear #ChooseActionNow #EarthGuardians', '#NewYear #ChooseActionNow #EarthGuardians', 'planned', 0, now())
insert into public.calendar_settings (key, value, updated_at) values
  ('default_year', to_jsonb(2026::int), now()),
  ('default_month', to_jsonb(12::int), now()),
  ('week_start', '"sunday"'::jsonb, now()),
  ('attention_note', 'Topics that need coverage this cycle — reorder with the arrows.'::jsonb, now())
