-- ============================================================================
-- Seed · Earth Guardians editorial calendar — December 2026
-- Generated by scripts/make-seed.mjs from /home/isa/EG-Posts/calendario-2026-12.json
-- Idempotent: re-running resets December 2026 and upserts the same topics.
-- ============================================================================

begin;

-- Reset December 2026 so re-seeding is deterministic.
delete from public.calendar_posts where year = 2026 and month = 12;

-- ------------------------------------------------------------- topics ---
on conflict (key) do update set
  label = excluded.label,
  description = excluded.description,
  color = excluded.color,
  emoji = excluded.emoji,
  sort = excluded.sort,
  needs_attention = excluded.needs_attention,
  attention_rank = excluded.attention_rank,
  updated_at = now();

delete from public.calendar_topics where key not in (
  'climate-action', 'fundraising-mobilizing', 'impact-restoration', 'awareness-days', 'crews-community', 'trainings-webinars', 'partners-collabs', 'indigenous-justice', 'water-oceans', 'leaders-bts'
) and not exists (select 1 from public.calendar_posts p where p.topic_key = calendar_topics.key);

-- -------------------------------------------------------------- posts ---
;

-- ------------------------------------------------------------ settings ---
on conflict (key) do update set value = excluded.value, updated_at = now();

commit;
